const templates = global.get("iec104_templates") || [];
const cmd = msg.payload;

// Chỉ xử lý khi là lệnh execute (bỏ qua select)
if (cmd.action !== "execute") {
    return null;
}

// Tìm mapping theo type & IOA
const matched = templates.find(e =>
    e.type === cmd.type && e.address === cmd.address
);

if (!matched) {
    node.warn(`Không tìm thấy mapping cho type ${cmd.type}, IOA ${cmd.address}`);
    return null;
}

// ===== BOOL → FC 05 (Write Single Coil) =====
if (matched.datatype === "bool" || matched.datatype === "boolean") {
    // Chuẩn hoá giá trị bool (nhận true/false, 1/0, "1"/"0")
    const b = !!(cmd.value === true || cmd.value === 1 || cmd.value === "1");

    // Một số thiết bị yêu cầu 0xFF00 cho ON, 0x0000 cho OFF.
    // Nếu bạn muốn dùng dạng này, thêm coilOn/coilOff vào template.
    const coilOn  = (matched.coilOn  !== undefined) ? matched.coilOn  : 1;       // hoặc 0xFF00
    const coilOff = (matched.coilOff !== undefined) ? matched.coilOff : 0;       // hoặc 0x0000

    msg.payload = {
        fc: 5,                                 // Write Single Coil
        unitid: matched.unitid,
        address: matched.modbusAddress,        // địa chỉ COIL
        value: b ? coilOn : coilOff,            // giá trị ON/OFF
        quantity:1
    };
    return msg;
}

// ===== Các kiểu số còn lại =====
const scale = (matched.scale != null) ? matched.scale : 1;
let value = Number(cmd.value) * scale;

const buf = Buffer.alloc(4); // đủ cho float32/uint32
let outPayload = {
    fc: 16,
    unitid: matched.unitid,
    address: matched.modbusAddress,
    quantity: 2,
    value: []
};

switch (matched.datatype) {
    case "int16":
    case "uint16":
        outPayload.fc = 6;            // Write Single Register
        outPayload.quantity = 1;
        outPayload.value = Math.round(value);
        break;

    case "int32":
        buf.writeInt32LE(Math.round(value));
        if (matched.byteOrder === "LEswap" || matched.byteOrder === "LE16swap") {
            outPayload.value = [buf.readUInt16LE(2), buf.readUInt16LE(0)];
        } else if (matched.byteOrder === "LE") {
            outPayload.value = [buf.readUInt16LE(0), buf.readUInt16LE(2)];
        } else {
            buf.writeInt32BE(Math.round(value));
            outPayload.value = [buf.readUInt16BE(0), buf.readUInt16BE(2)];
        }
        break;

    case "uint32":
        buf.writeUInt32LE(Math.round(value));
        if (matched.byteOrder === "LEswap" || matched.byteOrder === "LE16swap") {
            outPayload.value = [buf.readUInt16LE(2), buf.readUInt16LE(0)];
        } else if (matched.byteOrder === "LE") {
            outPayload.value = [buf.readUInt16LE(0), buf.readUInt16LE(2)];
        } else {
            buf.writeUInt32BE(Math.round(value));
            outPayload.value = [buf.readUInt16BE(0), buf.readUInt16BE(2)];
        }
        break;

    case "float":
    case "float32":
        if (matched.byteOrder === "LEswap" || matched.byteOrder === "LE16swap") {
            buf.writeFloatLE(value);
            outPayload.value = [buf.readUInt16LE(2), buf.readUInt16LE(0)];
        } else if (matched.byteOrder === "LE") {
            buf.writeFloatLE(value);
            outPayload.value = [buf.readUInt16LE(0), buf.readUInt16LE(2)];
        } else {
            buf.writeFloatBE(value);
            outPayload.value = [buf.readUInt16BE(0), buf.readUInt16BE(2)];
        }
        break;

    default:
        node.error("Kiểu dữ liệu không được hỗ trợ: " + matched.datatype);
        return null;
}

msg.payload = outPayload;
return msg;

// Convert Modbus to IEC104 template (updated)
// - Nếu msg.payload === "invalid"  => broadcast tất cả với QUALITY_INVALID
// - Nếu global.modbus_online === false => mọi điểm chuyển QUALITY_INVALID
// - Nếu online => gửi GOOD như bình thường

const iecTemplates = global.get("iec104_templates") || [];
const slaveId = msg.slaveId || "NM2-INV01";

const isOnline = global.get("modbus_online") !== false; // mặc định true nếu chưa set
let outMsgs = [];

// helper
function roundToDecimalPlaces(num, scale) {
  if (scale === 0 || scale === 1 || isNaN(scale)) return num;
  const decimals = Math.max(0, Math.round(-Math.log10(scale)));
  return parseFloat(num.toFixed(decimals));
}

// 1) Trường hợp được yêu cầu broadcast invalid
if (msg.payload === "invalid") {
  for (let entry of iecTemplates) {
    const key = entry.name;
    if (!key.startsWith(slaveId + "_")) continue;
    if (entry.type.startsWith("C_")) continue; // bỏ các type điều khiển

    outMsgs.push({
      payload: {
        type: entry.type,
        address: entry.address,
        value: 0,
        qualifier: "IEC60870_QUALITY_INVALID"
      }
    });
  }
  return [outMsgs];
}

// 2) Bình thường: map giá trị → IEC104
const dataObj = msg.payload || {};

for (let entry of iecTemplates) {
  const key = entry.name;
  if (!key.startsWith(slaveId + "_")) continue;
  if (entry.type.startsWith("C_")) continue; // bỏ các type điều khiển

  const field = key.substring(slaveId.length + 1);
  let value = 0;
  let qualifier = "IEC60870_QUALITY_INVALID";

  // ưu tiên key đầy đủ, sau đó field ngắn, sau cùng tới global
  let rawValue = dataObj[key];
  if (typeof rawValue === "undefined") rawValue = dataObj[field];
  if (typeof rawValue === "undefined") rawValue = global.get(key);

  // Nếu offline: luôn INVALID (ghi 0 cho an toàn)
  if (!isOnline) {
    outMsgs.push({
      payload: {
        type: entry.type,
        address: entry.address,
        value: 0,
        qualifier: "IEC60870_QUALITY_INVALID"
      }
    });
    continue;
  }

  // Online: chỉ GOOD khi là số hợp lệ
  if (typeof rawValue === "number" && !isNaN(rawValue)) {
    const scale = typeof entry.scale === "number" ? entry.scale : 1;
    const scaled = rawValue * scale;
    value = roundToDecimalPlaces(scaled, scale);
    qualifier = "IEC60870_QUALITY_GOOD";
  }

  outMsgs.push({
    payload: {
      type: entry.type,
      address: entry.address,
      value,
      qualifier
    }
  });
}

return [outMsgs];

// Lấy tất cả keys trong global context
const globalKeys = global.keys();
const allGlobals = {};

for (let i = 0; i < globalKeys.length; i++) {
    const key = globalKeys[i];
    allGlobals[key] = global.get(key);
