// - Các biến boolean luôn gửi, ép về 0/1
// - Nếu thiếu biến boolean trong payload, thử lấy từ global và ép về 0/1

const digitalKeys = [
    "p_Set_Exp_Enable",
    "p_Set_Total_Enable"
];

// Bổ sung biến digital nếu thiếu, lấy từ global
for (let key of digitalKeys) {
    const fullKey = "NM2-INV01_" + key;
    if (!(fullKey in msg.payload)) {
        const gVal = global.get(fullKey);
        if (typeof gVal === "boolean" || typeof gVal === "number") {
            msg.payload[fullKey] = gVal ? 1 : 0;
        }
    }
}

// Ép tất cả biến digital về 0/1 (nếu có trong payload)
for (let key of Object.keys(msg.payload)) {
    const shortKey = key.replace("NM2-INV01_", "");
    if (digitalKeys.includes(shortKey)) {
        const v = msg.payload[key];
        msg.payload[key] = v ? 1 : 0;
    }
}

// Không lọc gì nữa, chuyển tiếp toàn bộ
return msg;

const input = msg.payload;
const templates = global.get("iec104_templates") || [];

// Hàm làm tròn theo scale
function roundToDecimalPlaces(num, scale) {
    if (scale === 0 || scale === 1 || isNaN(scale)) return num;
    const decimals = Math.max(0, Math.round(-Math.log10(scale)));
    return parseFloat(num.toFixed(decimals));
}

// Danh sách biến cần lấy
const wantedKeys = [
