    const scale = template ? template.scale : 1;
    const rawValue = input[key];

    const scaled = rawValue * scale;
    result[key.replace("NM2-INV01_", "")] = roundToDecimalPlaces(scaled, scale);
}

// Gửi ra dạng SOL block
msg.payload = [{
    name: "S3Logger-VHouse-Det-TrungTien-Hanam",
    type: "104_SOL",
    ts: Math.floor(Date.now() / 1000),
