return msg;

// Check if the Internet is available (global context)
let internetAvailable = global.get('internetAvailable') || false;

// Retrieve the queue from the global context or initialize it as an empty array
let queue = flow.get('queue2') || [];  // Use flow context to ensure sharing between nodes
let maxQueueSize = 10000;  // Reduced max queue size 

// Get the last queue time or initialize it
let lastQueueTime = flow.get('lastQueueTime') || 0;
const currentTime = Date.now();
const queueInterval =  5 * 60 * 1000; // 10 minutes in milliseconds
