// Case 1: If the queue is empty and the Internet is available, send real-time data directly
if (internetAvailable && queue.length === 0) {
    node.status({ fill: "green", shape: "ring", text: "Sending Real-Time Data" });
    return [msg, null];  // Send real-time data to Output 1

// Case 2: If Internet is not available, queue new data at a reduced rate (every 5 minutes)
} else if (!internetAvailable) {
    // Check if it's time to queue a new entry (5 minute interval)
    if (currentTime - lastQueueTime >= queueInterval) {
        // Time to queue a new entry
        if (queue.length < maxQueueSize) {
            queue.push(msg.payload);  // Add data to the queue
            flow.set('queue2', queue);  // Save the updated queue in flow context
            flow.set('lastQueueTime', currentTime);  // Update last queue time

            node.status({ 
                fill: "yellow", 
                shape: "dot", 
                text: "Offline: Queued data (5min interval), Queue: " + queue.length 
            });

            node.warn("Internet Offline: Data queued at 5min interval, Queue size: " + queue.length);
        } else {
            node.warn("Queue size limit reached, discarding new data.");
            node.status({ fill: "red", shape: "dot", text: "Queue FULL! Size: " + queue.length });
        }
    } else {
        // Skip this data point as we're within the 5-minute interval
        node.status({ 
            fill: "blue", 
            shape: "ring", 
            text: "Offline: Skipping data point (" + Math.floor((queueInterval - (currentTime - lastQueueTime))/1000) + "s until next queue)"
        });
    }
    return [null, null];  // Do nothing while in offline mode

// Case 3: If there is data in the queue but Internet is available
} else {
    // Continue to queue new data normally while processing the backlog
    if (queue.length < maxQueueSize) {
        queue.push(msg.payload);  // Add data to the queue
        flow.set('queue2', queue);  // Save the updated queue in flow context

        node.status({ fill: "yellow", shape: "dot", text: "Queueing New Data, Queue Length: " + queue.length });
        node.warn("New Data Queued (online but processing backlog): " + JSON.stringify(msg.payload));
    } else {
        node.warn("Queue size limit reached, discarding new data.");
    }

    return [null, null];  // Do nothing while queuing data
}

// Check if the Internet is available (global context)
