// Retrieve the queue from the flow context or initialize it as an empty array
let queue = flow.get('queue2') || [];  // Initialize the queue if it doesn't exist
let maxQueueSize = 10000;            // Set the maximum queue size

// Case 1: Sending queued data when Internet is available and there is data in the queue
if (internetAvailable && queue.length > 0) {
    // Dequeue the oldest message for sending
    let queuedMessage = queue.shift();  // Get the first message from the queue
    flow.set('queue2', queue);  // Update the queue in context

    // Send the dequeued message (if it's not null or empty)
    if (queuedMessage) {
        node.status({ fill: "green", shape: "dot", text: "Sending Queued Data" });
        //node.warn("Sending Queued Data: " + JSON.stringify(queuedMessage));
        return [null, { payload: queuedMessage }];  // Send to output 2
    } else {
        //node.warn("Queue is empty, nothing to send.");
        return [null, null];  // Do nothing if the queue is empty
    }
} 

// Case 2: Internet is down, so queue new data
else if (!internetAvailable) {
    node.status({ fill: "red", shape: "dot", text: "No Internet, waiting to send queued data." });
    return [null, null];  // Do nothing while the internet is down
}

// Case 3: Internet is back but queue is empty
else {
    node.status({ fill: "grey", shape: "ring", text: "Queue is empty, waiting for new data..." });
    return [null, null];  // Do nothing when the queue is empty
}

if (msg.payload === false) {
    global.set('internetAvailable', false);
} else {
    global.set('internetAvailable', true);
