// Parse strongSwan `ipsec statusall` text in msg.payload
const text = String(msg.payload || "");

// Helper: escape regex
const escRe = s => s.replace(/[-/\\^$*+?.()|[\]{}]/g, "\\$&");

// --- Connection name (lấy từ phần Connections) ---
let conn = null;
{
  const mConn = text.match(/Connections:\s*?\n\s{2}([A-Za-z0-9._-]+):\s+%any/m);
  if (mConn) conn = mConn[1];
  else {
    // Fallback: dòng bất kỳ có dạng "  name:  %any"
    const mAlt = text.match(/\n\s{2}([A-Za-z0-9._-]+):\s+%any/m);
    if (mAlt) conn = mAlt[1];
  }
}

// --- Local/Remote IDs ---
const mLocal = text.match(/local:\s+\[([^\]]+)\]/);
const mRemote = text.match(/remote:\s+\[([^\]]+)\]/);

// --- Local/Remote subnets ---
const mChild = text.match(/child:\s+([0-9a-fA-F.:/]+)\s+===\s+([0-9a-fA-F.:/]+)/);

// --- SA counts ---
const mSAs = text.match(/Security Associations \((\d+)\s+up,\s+(\d+)\s+connecting\)/);

// --- IKE SA id [..] & CHILD SA id {..} ---
let ikeId = null, childId = null;
if (conn) {
  const reIke = new RegExp("\\b" + escRe(conn) + "\\[(\\d+)\\]:");
  const reChild = new RegExp("\\b" + escRe(conn) + "\\{(\\d+)\\}:");
  const mIke = text.match(reIke);
  const mChildId = text.match(reChild);
  ikeId = mIke ? Number(mIke[1]) : null;
  childId = mChildId ? Number(mChildId[1]) : null;
}

// --- Reauthentication remaining (IKE line) ---
let ike_reauth_in = null;
if (conn && ikeId != null) {
  const reIkeLine = new RegExp("\\b" + escRe(conn) + "\\[" + ikeId + "\\]\\:[\\s\\S]*?reauthentication in ([^,\\n]+)", "i");
  const mReauth = text.match(reIkeLine);
  ike_reauth_in = mReauth ? mReauth[1].trim() : null;
}

// --- Rekeying remaining (CHILD line)---
let child_rekey_in = null;
if (conn && childId != null) {
  const reChildLine = new RegExp("\\b" + escRe(conn) + "\\{" + childId + "\\}\\:[\\s\\S]*?rekeying in ([^,\\n]+)", "i");
  const mRekey = text.match(reChildLine);
  child_rekey_in = mRekey ? mRekey[1].trim() : null;
}

// --- Traffic: bytes_i / bytes_o, pkts, ages (tách riêng in/out) ---
const mIn = text.match(/(\d+)\s+bytes_i\s+\((\d+)\s+pkts,\s*([^)]+)\)/i);
const mOut = text.match(/(\d+)\s+bytes_o\s+\((\d+)\s+pkts,\s*([^)]+)\)/i);

const bytes_in = mIn ? Number(mIn[1]) : null;
const pkts_in = mIn ? Number(mIn[2]) : null;
const age_in = mIn ? mIn[3].trim() : null;

const bytes_out = mOut ? Number(mOut[1]) : null;
const pkts_out = mOut ? Number(mOut[2]) : null;
const age_out = mOut ? mOut[3].trim() : null;

// --- Build payload ---
msg.payload = {
  conn_name: conn || null,
  local_id: mLocal ? mLocal[1] : null,
  remote_id: mRemote ? mRemote[1] : null,
  local_subnet: mChild ? mChild[1] : null,
  remote_subnet: mChild ? mChild[2] : null,
  sa_up: mSAs ? Number(mSAs[1]) : null,
  sa_connecting: mSAs ? Number(mSAs[2]) : null,
  ike_sa_id: ikeId,
  child_sa_id: childId,
  ike_reauth_in,       // ví dụ: "3 hours"
  child_rekey_in,      // ví dụ: "19 minutes"
  bytes_in, pkts_in, age_in,
  bytes_out, pkts_out, age_out
};

return msg;

// Convert IPsec JSON -> INSERT trực tiếp (Via msg.topic, KHÔNG dùng params)
// Lưu ý: có escape chuỗi để tránh lỗi khi có dấu nháy đơn.

function q(v) { // quote string or NULL
  if (v === undefined || v === null || v === '') return 'NULL';
  return `'${String(v).replace(/'/g, "''")}'`;
}
function n(v) { // number or NULL
  if (v === undefined || v === null || v === '') return 'NULL';
  const num = Number(v);
  return Number.isFinite(num) ? String(num) : 'NULL';
}

// Parse payload
const raw = (typeof msg.payload === 'string')
  ? (() => { try { return JSON.parse(msg.payload); } catch (e) { return {}; } })()
  : (msg.payload || {});

// Chuẩn hoá trường
const v = {
  peer:           raw.conn_name ?? raw.peer ?? null,
  local_id:       raw.local_id ?? null,
  remote_id:      raw.remote_id ?? null,
  local_subnet:   raw.local_subnet ?? null,
  remote_subnet:  raw.remote_subnet ?? null,
  sa_up:          raw.sa_up,
  sa_connecting:  raw.sa_connecting,
  ike_sa_id:      raw.ike_sa_id,
  child_sa_id:    raw.child_sa_id,
  ike_reauth_in:  raw.ike_reauth_in ?? null,
  child_rekey_in: raw.child_rekey_in ?? null,
  bytes_in:       raw.bytes_in,
  pkts_in:        raw.pkts_in,
  age_in:         raw.age_in ?? null,
  bytes_out:      raw.bytes_out,
  pkts_out:       raw.pkts_out,
  age_out:        raw.age_out ?? null
};

// Timestamp kiểu bạn đang dùng
const now = Date.now(), tz = 7*3600*1000;
const ts_utc   = new Date(now).toISOString();                               // UTC ISO
const ts_local = new Date(now + tz).toISOString().replace('Z', '+07:00');   // ISO +07:00

// Build SQL gán trực tiếp vào msg.topic
msg.topic = `
INSERT INTO ipsec_log (
  ts_local, ts_utc,
  peer, local_id, remote_id,
  local_subnet, remote_subnet,
  sa_up, sa_connecting,
  ike_sa_id, child_sa_id,
  ike_reauth_in, child_rekey_in,
  bytes_in, pkts_in, age_in,
  bytes_out, pkts_out, age_out
) VALUES (
  ${q(ts_local)}, ${q(ts_utc)},
  ${q(v.peer)}, ${q(v.local_id)}, ${q(v.remote_id)},
  ${q(v.local_subnet)}, ${q(v.remote_subnet)},
  ${n(v.sa_up)}, ${n(v.sa_connecting)},
  ${n(v.ike_sa_id)}, ${n(v.child_sa_id)},
  ${q(v.ike_reauth_in)}, ${q(v.child_rekey_in)},
  ${n(v.bytes_in)}, ${n(v.pkts_in)}, ${q(v.age_in)},
  ${n(v.bytes_out)}, ${n(v.pkts_out)}, ${q(v.age_out)}
);
`;

// (Tùy chọn) hiển thị preview_sql cho dễ debug
msg.preview_sql = msg.topic;

node.status({ fill: "green", shape: "dot", text: `INSERT ${v.peer || ''}` });
return msg;

// Latest row (ưu tiên theo ts_utc rồi ts_local)
msg.topic = `
SELECT *
FROM ipsec_log
ORDER BY ts_utc DESC, ts_local DESC, rowid DESC
LIMIT 1;
`;
return msg;

/***** Alert v2 — 3 outputs *****
Output 1: One-shot ALERT (edge UP→DOWN) — dùng để gửi mail/notify
Output 2: Pass-through khi hệ thống OK (UP)
Output 3: Trigger cho Exec (sudo ipsec reload) — level-trigger khi đang DOWN, không phụ thuộc latch
*********************************/

const SEND_RECOVERY        = false;
const RELOAD_CMD           = "sudo ipsec reload";
const RELOAD_THROTTLE_MIN  = 0; // 0 = bắn mỗi lần còn DOWN; >0 = giới hạn theo phút

function toNum(v) {
  const n = Number(v);
  return Number.isFinite(n) ? n : NaN;
}

// Dò số theo nhiều đường dẫn có thể gặp trong payload
function pickNumWithPath(root, keys) {
  for (const k of keys) {
    try {
      let cur = root;
      if (k === "") continue;
      const parts = k.replace(/\[(\d+)\]/g, '.$1').split('.').filter(Boolean);
      for (const p of parts) cur = cur?.[p];
      const n = toNum(cur);
      if (!Number.isNaN(n)) return { value: n, path: k };
    } catch { /* ignore */ }
  }
  return { value: NaN, path: "" };
}

// Dò text theo nhiều đường dẫn
function pickTextWithPath(root, keys) {
  for (const k of keys) {
    try {
      let cur = root;
      if (k === "") continue;
      const parts = k.replace(/\[(\d+)\]/g, '.$1').split('.').filter(Boolean);
      for (const p of parts) cur = cur?.[p];
      if (cur !== undefined && cur !== null && String(cur).trim() !== "") {
        return { value: String(cur), path: k };
      }
    } catch { /* ignore */ }
  }
  return { value: "", path: "" };
}

// Chuẩn hoá input
let root = msg;
try {
  if (typeof msg.payload === "string") root = { payload: JSON.parse(msg.payload) };
} catch { /* giữ nguyên */ }

// Các đường dẫn thường gặp
const keySets = {
  sa_up: [
    "payload.0.sa_up","payload[0].sa_up","[0].payload.sa_up","[0].sa_up",
    "payload.sa_up","data.sa_up","sa_up"
  ],
  sa_connecting: [
    "payload.0.sa_connecting","payload[0].sa_connecting","[0].payload.sa_connecting","[0].sa_connecting",
    "payload.sa_connecting","data.sa_connecting","sa_connecting"
  ],
  ike_sa_id: [
    "payload.0.ike_sa_id","payload[0].ike_sa_id","[0].payload.ike_sa_id","[0].ike_sa_id",
    "payload.ike_sa_id","data.ike_sa_id","ike_sa_id"
  ],
  peer: [
    "payload.0.peer","payload[0].peer","[0].payload.peer","[0].peer","payload.peer","data.peer","peer"
  ],
  local_id: [
    "payload.0.local_id","payload[0].local_id","[0].payload.local_id","[0].local_id","payload.local_id","data.local_id","local_id"
  ],
  remote_id: [
    "payload.0.remote_id","payload[0].remote_id","[0].payload.remote_id","[0].remote_id","payload.remote_id","data.remote_id","remote_id"
  ]
};

const up  = pickNumWithPath(root, keySets.sa_up);
const con = pickNumWithPath(root, keySets.sa_connecting);
const chi = pickNumWithPath(root, keySets.ike_sa_id);

const haveAll = [up,con,chi].every(x => Number.isFinite(x.value));
if (!haveAll) {
  node.status({ fill: "yellow", shape: "ring", text: "Thiếu dữ liệu sa_up/connecting/child" });
  return null;
}

const statusText = `up=${up.value}(${up.path}) | conn=${con.value}(${con.path}) | child=${chi.value}(${chi.path})`;

// Lấy thêm vài thông tin để ghép nội dung ngắn gọn, tránh [object Object]
const peer  = pickTextWithPath(root, keySets.peer).value || "-";
const lid   = pickTextWithPath(root, keySets.local_id).value || "-";
const rid   = pickTextWithPath(root, keySets.remote_id).value || "-";

// Điều kiện DOWN
const cond_sa_down         = (up.value < 1);
const cond_connecting_down = (con.value === 1 && up.value === 0);
const cond_child_low       = (chi.value < 1);
const needAlert            = cond_sa_down || cond_connecting_down || cond_child_low;

// Latch trạng thái
const prevState = context.get("vpn_state") || "INIT";
let latched     = !!context.get("vpn_alarm_latched");

// Chuẩn bị outputs
let out1 = null; // one-shot alert (string payload cho node Prepare VPN Error Email)
let out2 = null; // OK pass-through
let out3 = null; // trigger Exec (level-trigger when DOWN)

// Chống spam reload theo phút cho Output 3
const nowMs = Date.now();
const lastReloadMs = context.get("last_reload_emit_ms") || 0;
const allowReload = RELOAD_THROTTLE_MIN <= 0
  ? true
  : (nowMs - lastReloadMs) >= RELOAD_THROTTLE_MIN * 60 * 1000;

if (needAlert) {
  // Lý do
  const reasons = [];
  if (cond_sa_down) reasons.push("sa_up < 1");
  if (cond_connecting_down) reasons.push("sa_up = 0 (trạng thái Established không hoạt động)");
  if (cond_child_low) reasons.push("ike_sa_id < 1");

  // Status đỏ
  node.status({ fill: "red", shape: "dot", text: `DOWN (A=1) | ${statusText}` });

  // ✅ Output 1: chỉ bắn khi EDGE (UP→DOWN) hoặc INIT→DOWN nếu chưa latched
  if (prevState !== "DOWN" || !latched) {
    const whenLocal = new Date().toLocaleString('vi-VN');
    const reasonStr = reasons.length ? reasons.join("; ") : "Không rõ";
    const human =
`Peer: ${peer}
Local ID / Remote ID: ${lid} / ${rid}
Trạng thái: DOWN
Lý do: ${reasonStr}
Chỉ số: up=${up.value}, connecting=${con.value}, ike_sa_id=${chi.value}
Thời điểm: ${whenLocal}`;

    out1 = {
      topic: "⚠️ IPsec alert",
      // QUAN TRỌNG: payload là STRING để node Prepare VPN Error Email dùng trực tiếp
      payload: human,
      // Giữ thêm dữ liệu gốc để debug/đính kèm nếu cần
      data: { reasons, metrics: { sa_up: up.value, sa_connecting: con.value, ike_sa_id: chi.value }, ts: new Date().toISOString(), raw: root }
    };
    latched = true;
  }

  // Output 3: luôn bắn khi đang DOWN (level-trigger)
  if (allowReload) {
    out3 = {
      topic: "IPsec reload",
      payload: RELOAD_CMD, // Nếu Exec đã có command sẵn thì payload có thể trống
      reason: "DOWN",
      metrics: { sa_up: up.value, sa_connecting: con.value, ike_sa_id: chi.value },
      ts: new Date().toISOString()
    };
    context.set("last_reload_emit_ms", nowMs);
  }

  context.set("vpn_state", "DOWN");
  context.set("vpn_alarm_latched", latched);
  return [out1, null, out3];

} else {
  // OK
  node.status({ fill: "green", shape: "ring", text: `UP (A=0) | ${statusText}` });

  // Output 1: tuỳ chọn gửi “đã khôi phục”
  if (prevState === "DOWN") {
    context.set("vpn_alarm_latched", false);
    if (SEND_RECOVERY) {
      const whenLocal = new Date().toLocaleString('vi-VN');
      const human =
`Peer: ${peer}
Local ID / Remote ID: ${lid} / ${rid}
Trạng thái: ĐÃ KHÔI PHỤC (UP)
Chỉ số: up=${up.value}, connecting=${con.value}, ike_sa_id=${chi.value}
Thời điểm: ${whenLocal}`;

      out1 = {
        topic: "✅ IPsec đã khôi phục",
        payload: human, // để node Prepare dùng chung
        data: { metrics: { sa_up: up.value, sa_connecting: con.value, ike_sa_id: chi.value }, ts: new Date().toISOString(), raw: root }
      };
    }
  }

  // Output 2: pass-through khi OK
  out2 = { topic: "IPsec OK", payload: root };

  context.set("vpn_state", "UP");
  return [out1, out2, null];
}
